create or replace function public.factory_dispatch_next_planned_task(p_project_key text) returns jsonb language plpgsql security invoker set search_path='' as $$ declare v_project_id uuid;v_task public.factory_tasks%rowtype;v_run_id uuid;begin select id into v_project_id from public.factory_projects where project_key=btrim(p_project_key) and is_active=true;if v_project_id is null then raise exception 'active project not found';end if;select * into v_task from public.factory_tasks where project_id=v_project_id and status='queued' and external_key like 'plan-%' order by created_at for update skip locked limit 1;if v_task.id is null then return null;end if;insert into public.factory_runs(task_id,status,metadata) values(v_task.id,'created',jsonb_build_object('dispatch_pending',true,'source','engineering-plan')) returning id into v_run_id;update public.factory_tasks set status='dispatching',updated_at=now() where id=v_task.id;insert into public.factory_audit_events(project_id,task_id,run_id,actor_type,actor_ref,event_type,payload) values(v_project_id,v_task.id,v_run_id,'system','backlog-dispatcher','task.dispatch.claimed','{}'::jsonb);return jsonb_build_object('run_id',v_run_id,'task_id',v_task.id,'project_id',v_project_id,'project_key',p_project_key,'title',v_task.title,'description',v_task.description,'complexity',v_task.complexity,'risk',v_task.risk,'metadata',jsonb_build_object('acceptance_criteria',v_task.acceptance_criteria,'depends_on',v_task.depends_on));end;$$;
revoke all on function public.factory_dispatch_next_planned_task(text) from public,anon,authenticated;grant execute on function public.factory_dispatch_next_planned_task(text) to service_role;
create or replace function public.factory_record_dispatch_decision(p_run_id uuid,p_route text,p_codex_level integer,p_codex_used boolean,p_human_gate boolean,p_gate_reasons jsonb) returns void language plpgsql security invoker set search_path='' as $$ declare v_task_id uuid;v_project_id uuid;begin if p_route not in ('direct','codex') then raise exception 'invalid route';end if;select r.task_id,t.project_id into v_task_id,v_project_id from public.factory_runs r join public.factory_tasks t on t.id=r.task_id where r.id=p_run_id for update of r;if v_task_id is null then raise exception 'run not found';end if;update public.factory_runs set execution_route=p_route,status=case when p_human_gate then 'awaiting_human' else 'queued' end,metadata=metadata||jsonb_build_object('dispatch_pending',false,'codex_level',p_codex_level,'codex_used',p_codex_used,'human_gate_required',p_human_gate,'gate_reasons',coalesce(p_gate_reasons,'[]'::jsonb)) where id=p_run_id;update public.factory_tasks set status=case when p_human_gate then 'awaiting_human' else 'queued_execution' end,updated_at=now() where id=v_task_id;insert into public.factory_decisions(project_id,task_id,decision_type,question,decision,decided_by) values(v_project_id,v_task_id,'execution_route',null,jsonb_build_object('route',p_route,'codex_level',p_codex_level,'codex_used',p_codex_used,'human_gate_required',p_human_gate,'gate_reasons',coalesce(p_gate_reasons,'[]'::jsonb)),'ai-product-factory');insert into public.factory_codex_usage(run_id,policy_level,invocation_count,reason,reported_usage) values(p_run_id,p_codex_level,0,coalesce(p_gate_reasons,'[]'::jsonb),'{}'::jsonb);end;$$;
revoke all on function public.factory_record_dispatch_decision(uuid,text,integer,boolean,boolean,jsonb) from public,anon,authenticated;grant execute on function public.factory_record_dispatch_decision(uuid,text,integer,boolean,boolean,jsonb) to service_role;
